}

export interface Timesheet {
  id: string;
  missionId: string;
  periodStart: string; // Date du début de semaine/mois
  periodEnd: string;
  totalHours: number;
  days: { date: string; hours: number; note?: string }[];
  status: TimesheetStatus;
  rejectionReason?: string;
}

// Structure pour les actions IA
export interface AIAction {
  type: 'CREATE_MISSION' | 'VALIDATE_TIMESHEET' | 'VIEW_DETAILS';
  payload: any;
  label: string;
