    hard: string[];
    soft: string[];
  };
  languages: string[];
  certifications: string[];
  detectedLanguage: string;
  jobCategory: string;
  totalExperienceYears: number;
  performanceScore: number;
  analysisDuration?: number;
}

export interface Experience {
  title: string;
  company: string;
  dates: string;
  description: string;
}

export interface Education {
  degree: string;
  school: string;
  dates: string;
}

export interface ChatMessage {
    role: 'user' | 'model';
    text: string;
    action?: AIAction; // New: Support for actionable buttons
}

export type View = 'upload' | 'dashboard' | 'favorites' | 'settings' | 'compare' | 'ai' | 'recruitment' | 'history' | 'infra' | 'missions' | 'timesheets';
export type Theme = 'light' | 'dark' | 'system';

export interface User {
  id: string;
  email: string;
}

export interface FilterCriteria {
  jobCategories: string[];
  locations: string[];
  experienceLevels: string[];
  skills: string[];
}

export interface RecruitmentData {
  candidateId: string;
  applicationDate: string;
  interview1Date: string;
  interview1Result: 'Excellent' | 'Good' | 'Fair' | 'Medium' | '';
  challengeSentDate: string;
  challengeDoneDate: string; // Can be empty if not done
  interview2Date: string;
  interview2Result: 'Excellent' | 'Good' | 'Fair' | 'Medium' | '';
  startDate: string;
}

export interface PipelineSnapshot {
  id: string;
  date: string;
  data: (RecruitmentData & { profile: CandidateProfile })[];
  count: number;
}

// --- NEW MODULES ---

export type ContractType = 'CDI' | 'CDD' | 'FREELANCE' | 'INTERIM' | 'STAGE';
export type MissionStatus = 'Draft' | 'Active' | 'Ended' | 'Paused';
export type TimesheetStatus = 'Draft' | 'Pending' | 'Validated' | 'Rejected';

export interface Mission {
  id: string;
  candidateId: string;
  candidateName: string;
  client: string;
  title: string;
  contractType: ContractType;
  startDate: string;
  endDate?: string;
  location: string;
  rate: number;
  currency: string;
  status: MissionStatus;
  timeTrackingEnabled: boolean;
}

export interface Timesheet {
  id: string;
  missionId: string;
  consultantName: string;
  clientName: string;
  periodStart: string;
  periodEnd: string;
  totalHours: number;
  days: { date: string; hours: number; note?: string }[];
  status: TimesheetStatus;
  rejectionReason?: string;
}

export interface AIAction {
  type: 'CREATE_MISSION' | 'VALIDATE_TIMESHEET' | 'GO_TO_TIMESHEETS';
  payload: any;
  label: string;
}

