};

// FIX: Changed React import to namespace import `* as React` to resolve widespread JSX intrinsic element type errors, which likely stem from a project configuration that requires this import style.
// FIX: Switched to namespace React import to correctly populate the global JSX namespace.
import * as React from 'react';
import { Icon } from './icons';
import { View } from '../types';
import { useTranslation } from '../i18n';
import { logoDark, logoIcon, logoLight } from '../assets';

interface SidebarProps {
  currentView: View;
  setCurrentView: (view: View) => void;
  isCollapsed: boolean;
  setIsCollapsed: (isCollapsed: boolean) => void;
  isMobileOpen: boolean;
  setIsMobileOpen: (isOpen: boolean) => void;
  isOwner: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ currentView, setCurrentView, isCollapsed, setIsCollapsed, isMobileOpen, setIsMobileOpen, isOwner }) => {
  const { t } = useTranslation();

  const recruitmentItems = [
    { id: 'upload', label: t('sidebar.upload'), icon: 'upload' },
    { id: 'dashboard', label: t('sidebar.dashboard'), icon: 'dashboard' },
    { id: 'recruitment', label: t('sidebar.recruitment'), icon: 'users' },
    { id: 'compare', label: t('sidebar.compare'), icon: 'compare' },
  ];

  const managementItems = [
    { id: 'missions', label: t('sidebar.missions'), icon: 'briefcase' },
    { id: 'timesheets', label: t('sidebar.timesheets'), icon: 'clock' },
  ];

  const toolItems = [
    { id: 'history', label: t('sidebar.history'), icon: 'history' },
    { id: 'ai', label: t('sidebar.ai_assistant'), icon: 'bot' },
    { id: 'favorites', label: t('sidebar.favorites'), icon: 'heart' },
    { id: 'settings', label: t('sidebar.settings'), icon: 'settings' },
  ];

  if (isOwner) {
      toolItems.push({ id: 'infra', label: t('sidebar.infra'), icon: 'activity' });
  }

  const sidebarClasses = `
    h-full bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-800
    flex flex-col z-40 transition-all duration-300 ease-in-out
    fixed md:static inset-y-0 left-0 transform md:transform-none
    ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'}
    ${isCollapsed ? 'w-20' : 'w-64'} flex-shrink-0
  `;

  const NavGroup = ({ title, items }: { title: string, items: typeof recruitmentItems }) => (
      <div className="mb-4">
          <div className={`px-4 mb-2 text-xs font-semibold text-gray-400 uppercase tracking-wider ${isCollapsed ? 'hidden' : 'block'}`}>
              {title}
          </div>
          {items.map((item) => (
            <button
              key={item.id}
              onClick={() => {
                setCurrentView(item.id as View);
                setIsMobileOpen(false);
              }}
              title={isCollapsed ? item.label : undefined}
              className={`w-full flex items-center p-3 rounded-lg ltr:text-left rtl:text-right rtl:flex-row-reverse transition-colors mb-1 ${
                isCollapsed ? 'justify-center' : 'gap-3'
              } ${
                currentView === item.id
                  ? 'bg-primary-100 text-primary-700 dark:bg-primary-900/50 dark:text-primary-200'
                  : 'text-gray-600 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-800'
              }`}
            >
              <div className={`flex-shrink-0 flex items-center justify-center ${isCollapsed ? 'w-10 h-10 rounded-md' : 'w-8'}`}>
                <Icon name={item.icon} className="w-5 h-5" />
              </div>
              <span className={`transition-opacity duration-200 ${isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100 text-sm font-medium'}`}>{item.label}</span>
            </button>
          ))}
      </div>
  );

  return (
    <>
      {isMobileOpen && <div onClick={() => setIsMobileOpen(false)} className="fixed inset-0 bg-black/50 z-30 md:hidden" />}
      <aside className={sidebarClasses}>
        <div className={`p-4 h-16 border-b border-gray-200 dark:border-gray-800 flex items-center ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
          <div className={`flex items-center gap-2 overflow-hidden transition-all duration-300 ${isCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'}`}>
            <img src={logoLight} alt="ParseLIQ HR" className="h-8 dark:hidden" />
            <img src={logoDark} alt="ParseLIQ HR" className="h-8 hidden dark:block" />
          </div>

          <button onClick={() => setIsCollapsed(!isCollapsed)} className="hidden md:block p-1 text-gray-500 hover:text-gray-200">
            <Icon name="panel-left" className={`w-6 h-6 transition-transform duration-300 ${isCollapsed ? 'rotate-180' : ''}`}/>
          </button>
           <button onClick={() => setIsMobileOpen(false)} className="md:hidden p-1 text-gray-500 hover:text-gray-200">
            <Icon name="close" className="w-6 h-6"/>
          </button>
        </div>

        <nav className="flex-1 p-2 overflow-y-auto">
          <NavGroup title="Recrutement" items={recruitmentItems} />
          <NavGroup title="Gestion" items={managementItems} />
          <NavGroup title="Outils" items={toolItems} />
        </nav>

        <footer className={`p-4 border-t border-gray-200 dark:border-gray-800 flex items-center gap-2 ${isCollapsed ? 'justify-center' : ''}`}>
           <img src={logoIcon} alt="ParseLIQ HR Icon" className="w-6 h-6"/>
           <a href="https://bento.me/moslih84" target="_blank" rel="noopener noreferrer" className={`text-sm text-gray-500 dark:text-gray-400 hover:underline transition-opacity duration-200 ${isCollapsed ? 'opacity-0 w-0 h-0' : 'opacity-100'}`}>
              {t('sidebar.footer')}
            </a>
        </footer>
      </aside>
    </>
  );
};

import * as React from 'react';
import { Mission, CandidateProfile, MissionStatus, ContractType } from '../types';
import { useTranslation } from '../i18n';
import { Icon } from './icons';
import { Drawer } from './Drawer';

interface MissionsViewProps {
    missions: Mission[];
    candidates: CandidateProfile[];
    onUpdateMission: (mission: Mission) => void;
    onCreateMission: (mission: Mission) => void;
}

export const MissionsView: React.FC<MissionsViewProps> = ({ missions, candidates, onUpdateMission, onCreateMission }) => {
    const { t } = useTranslation();
    const [isDrawerOpen, setIsDrawerOpen] = React.useState(false);
    const [editingMission, setEditingMission] = React.useState<Partial<Mission>>({});

    // Form state
    const [selectedCandidateId, setSelectedCandidateId] = React.useState('');
    const [client, setClient] = React.useState('');
    const [title, setTitle] = React.useState('');
    const [contractType, setContractType] = React.useState<ContractType>('FREELANCE');
    const [status, setStatus] = React.useState<MissionStatus>('Draft');
    const [startDate, setStartDate] = React.useState('');
    const [endDate, setEndDate] = React.useState('');
    const [rate, setRate] = React.useState(0);
    const [location, setLocation] = React.useState('');

    const handleOpenCreate = () => {
        setEditingMission({});
        // Reset form
        setSelectedCandidateId('');
        setClient('');
        setTitle('');
        setContractType('FREELANCE');
        setStatus('Draft');
        setStartDate('');
        setEndDate('');
        setRate(0);
        setLocation('');
        setIsDrawerOpen(true);
    };

    const handleEdit = (mission: Mission) => {
        setEditingMission(mission);
        setSelectedCandidateId(mission.candidateId);
        setClient(mission.client);
        setTitle(mission.title);
        setContractType(mission.contractType);
        setStatus(mission.status);
        setStartDate(mission.startDate);
        setEndDate(mission.endDate || '');
        setRate(mission.rate);
        setLocation(mission.location);
        setIsDrawerOpen(true);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const candidate = candidates.find(c => c.id === selectedCandidateId);

        const missionData: Mission = {
            id: editingMission.id || `mission-${Date.now()}`,
            candidateId: selectedCandidateId,
            candidateName: candidate?.name || 'Unknown',
            client,
            title,
            contractType,
            status,
            startDate,
            endDate,
            rate,
            currency: 'EUR',
            location,
            timeTrackingEnabled: true
        };

        if (editingMission.id) {
            onUpdateMission(missionData);
        } else {
            onCreateMission(missionData);
        }
        setIsDrawerOpen(false);
    };

    const getStatusColor = (status: MissionStatus) => {
        switch(status) {
            case 'Active': return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300';
            case 'Draft': return 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300';
            case 'Ended': return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300';
            case 'Paused': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300';
            default: return 'bg-gray-100';
        }
    };

    return (
        <div className="p-4 sm:p-8 space-y-6 h-full flex flex-col">
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-3xl font-bold font-display text-gray-800 dark:text-gray-100">{t('sidebar.missions')}</h2>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Gérez vos consultants et projets en cours.</p>
                </div>
                <button onClick={handleOpenCreate} className="bg-gradient-button text-white font-bold py-2 px-4 rounded-full flex items-center gap-2">
                    <Icon name="plus" className="w-5 h-5"/>
                    <span>Nouvelle Mission</span>
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {missions.map(mission => (
                    <div key={mission.id} onClick={() => handleEdit(mission)} className="bg-white dark:bg-gray-800 p-6 rounded-xl border dark:border-gray-700 shadow-sm hover:shadow-md transition-all cursor-pointer group">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h3 className="font-bold text-lg text-gray-900 dark:text-white group-hover:text-primary-600 transition-colors">{mission.title}</h3>
                                <p className="text-sm text-gray-500">{mission.client}</p>
                            </div>
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${getStatusColor(mission.status)}`}>
                                {mission.status}
                            </span>
                        </div>

                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-10 h-10 rounded-full bg-primary-100 dark:bg-primary-900/30 flex items-center justify-center text-primary-700 font-bold">
                                {mission.candidateName.charAt(0)}
                            </div>
                            <div>
                                <p className="font-semibold text-sm">{mission.candidateName}</p>
                                <p className="text-xs text-gray-500">{mission.contractType}</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 text-sm border-t dark:border-gray-700 pt-4">
                            <div>
                                <span className="block text-xs text-gray-500 mb-1">Taux / Salaire</span>
                                <span className="font-mono font-medium">{mission.rate} {mission.currency}</span>
                            </div>
                            <div>
                                <span className="block text-xs text-gray-500 mb-1">Lieu</span>
                                <span className="truncate block">{mission.location}</span>
                            </div>
                            <div className="col-span-2">
                                <span className="block text-xs text-gray-500 mb-1">Période</span>
                                <span className="font-medium">{mission.startDate} <Icon name="arrow-right" className="w-3 h-3 inline mx-1"/> {mission.endDate || 'Indéfini'}</span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            <Drawer isOpen={isDrawerOpen} onClose={() => setIsDrawerOpen(false)} title={editingMission.id ? "Modifier Mission" : "Nouvelle Mission"}>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Candidat</label>
                        <select 
                            value={selectedCandidateId} 
                            onChange={e => setSelectedCandidateId(e.target.value)}
                            className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            required
                        >
                            <option value="">Sélectionner un candidat</option>
                            {candidates.map(c => (
                                <option key={c.id} value={c.id}>{c.name}</option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Client / Projet</label>
                        <input 
                            type="text" 
                            value={client} 
                            onChange={e => setClient(e.target.value)}
                            className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            required
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Intitulé du poste</label>
                        <input 
                            type="text" 
                            value={title} 
                            onChange={e => setTitle(e.target.value)}
                            className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            required
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1 dark:text-gray-300">Type de contrat</label>
                            <select 
                                value={contractType} 
                                onChange={e => setContractType(e.target.value as ContractType)}
                                className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            >
                                <option value="FREELANCE">Freelance</option>
                                <option value="CDI">CDI</option>
                                <option value="CDD">CDD</option>
                                <option value="INTERIM">Intérim</option>
                                <option value="STAGE">Stage</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1 dark:text-gray-300">Statut</label>
                            <select 
                                value={status} 
                                onChange={e => setStatus(e.target.value as MissionStatus)}
                                className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            >
                                <option value="Draft">Brouillon</option>
                                <option value="Active">Active</option>
                                <option value="Paused">En pause</option>
                                <option value="Ended">Terminée</option>
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1 dark:text-gray-300">Début</label>
                            <input 
                                type="date" 
                                value={startDate} 
                                onChange={e => setStartDate(e.target.value)}
                                className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1 dark:text-gray-300">Fin (optionnel)</label>
                            <input 
                                type="date" 
                                value={endDate} 
                                onChange={e => setEndDate(e.target.value)}
                                className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1 dark:text-gray-300">TJM / Salaire</label>
                            <input 
                                type="number" 
                                value={rate} 
                                onChange={e => setRate(Number(e.target.value))}
                                className="w-full p-2 rounded border dark:bg-gray-800 dark:border-gray-700"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1 dark:text-gray-300">Lieu</label>
                            <input 
                                type="text" 
                                value={location} 
