    const [location, setLocation] = React.useState('');

    React.useEffect(() => {
        if (isDrawerOpen) {
            setAnimateSidebar(true);
            document.body.style.overflow = 'hidden';
        } else {
            const timer = setTimeout(() => setAnimateSidebar(false), 300);
            document.body.style.overflow = 'unset';
            return () => clearTimeout(timer);
        }
    }, [isDrawerOpen]);

    const handleOpenCreate = () => {
        setEditingMission({});
        // Reset form
        setSelectedCandidateId('');
        setClient('');
        setTitle('');
        setContractType('FREELANCE');
        setStatus('Draft');
        setStartDate('');
        setEndDate('');
        setRate(0);
        setLocation('');
        setIsDrawerOpen(true);
    };

    const handleEdit = (mission: Mission) => {
        setEditingMission(mission);
        setSelectedCandidateId(mission.candidateId);
        setClient(mission.client);
        setTitle(mission.title);
        setContractType(mission.contractType);
        setStatus(mission.status);
        setStartDate(mission.startDate);
        setEndDate(mission.endDate || '');
        setRate(mission.rate);
        setLocation(mission.location);
        setIsDrawerOpen(true);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const candidate = candidates.find(c => c.id === selectedCandidateId);

        const missionData: Mission = {
            id: editingMission.id || `mission-${Date.now()}`,
            candidateId: selectedCandidateId,
            candidateName: candidate?.name || 'Unknown',
            client,
            title,
            contractType,
            status,
            startDate,
            endDate,
            rate,
            currency: 'EUR',
            location,
            timeTrackingEnabled: true
        };

        if (editingMission.id) {
            onUpdateMission(missionData);
        } else {
            onCreateMission(missionData);
        }
        setIsDrawerOpen(false);
    };

    const getStatusColor = (status: MissionStatus) => {
        switch(status) {
            case 'Active': return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300';
            case 'Draft': return 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300';
            case 'Ended': return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300';
            case 'Paused': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300';
            default: return 'bg-gray-100';
        }
    };

    return (
        <div className="p-4 sm:p-8 space-y-6 h-full flex flex-col">
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-3xl font-bold font-display text-gray-800 dark:text-gray-100">{t('sidebar.missions')}</h2>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Gérez vos consultants et projets en cours.</p>
                </div>
                <button onClick={handleOpenCreate} className="bg-gradient-button text-white font-bold py-2 px-4 rounded-full flex items-center gap-2 shadow-md hover:shadow-lg transition-all hover:scale-105">
                    <Icon name="plus" className="w-5 h-5"/>
                    <span>Nouvelle Mission</span>
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {missions.map(mission => (
                    <div key={mission.id} onClick={() => handleEdit(mission)} className="bg-white dark:bg-gray-800 p-6 rounded-xl border dark:border-gray-700 shadow-sm hover:shadow-md transition-all cursor-pointer group">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h3 className="font-bold text-lg text-gray-900 dark:text-white group-hover:text-primary-600 transition-colors">{mission.title}</h3>
                                <p className="text-sm text-gray-500">{mission.client}</p>
                            </div>
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${getStatusColor(mission.status)}`}>
                                {mission.status}
                            </span>
                        </div>

                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-10 h-10 rounded-full bg-primary-100 dark:bg-primary-900/30 flex items-center justify-center text-primary-700 font-bold">
                                {mission.candidateName.charAt(0)}
                            </div>
                            <div>
                                <p className="font-semibold text-sm">{mission.candidateName}</p>
                                <p className="text-xs text-gray-500">{mission.contractType}</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 text-sm border-t dark:border-gray-700 pt-4">
                            <div>
                                <span className="block text-xs text-gray-500 mb-1">Taux / Salaire</span>
                                <span className="font-mono font-medium">{mission.rate} {mission.currency}</span>
                            </div>
                            <div>
                                <span className="block text-xs text-gray-500 mb-1">Lieu</span>
                                <span className="truncate block">{mission.location}</span>
                            </div>
                            <div className="col-span-2">
                                <span className="block text-xs text-gray-500 mb-1">Période</span>
                                <span className="font-medium">{mission.startDate} <Icon name="arrow-right" className="w-3 h-3 inline mx-1"/> {mission.endDate || 'Indéfini'}</span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Sidebar Modal (replacing Drawer) */}
            {(isDrawerOpen || animateSidebar) && (
                <div className={`fixed inset-0 z-[60] flex justify-end transition-opacity duration-300 ${isDrawerOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setIsDrawerOpen(false)} />
                    <div 
                        className={`relative w-full md:w-1/2 h-full bg-white dark:bg-gray-900 shadow-2xl flex flex-col transform transition-transform duration-300 ease-out ${isDrawerOpen ? 'translate-x-0' : 'translate-x-full'}`}
                    >
                        <div className="flex justify-between items-center p-6 border-b dark:border-gray-800">
                            <h3 className="text-2xl font-bold font-display text-gray-900 dark:text-white">
                                {editingMission.id ? "Modifier Mission" : "Nouvelle Mission"}
                            </h3>
                            <button onClick={() => setIsDrawerOpen(false)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors">
                                <Icon name="close" className="w-6 h-6 text-gray-500" />
                            </button>
                        </div>

                        <div className="p-6 overflow-y-auto flex-1">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div>
                                    <label className="block text-sm font-medium mb-1 dark:text-gray-300">Candidat</label>
                                    <select 
                                        value={selectedCandidateId} 
                                        onChange={e => setSelectedCandidateId(e.target.value)}
                                        className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        required
                                    >
                                        <option value="">Sélectionner un candidat</option>
                                        {candidates.map(c => (
                                            <option key={c.id} value={c.id}>{c.name}</option>
                                        ))}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-1 dark:text-gray-300">Client / Projet</label>
                                    <input 
                                        type="text" 
                                        value={client} 
                                        onChange={e => setClient(e.target.value)}
                                        className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        required
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-1 dark:text-gray-300">Intitulé du poste</label>
                                    <input 
                                        type="text" 
                                        value={title} 
                                        onChange={e => setTitle(e.target.value)}
                                        className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        required
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Type de contrat</label>
                                        <select 
                                            value={contractType} 
                                            onChange={e => setContractType(e.target.value as ContractType)}
                                            className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        >
                                            <option value="FREELANCE">Freelance</option>
                                            <option value="CDI">CDI</option>
                                            <option value="CDD">CDD</option>
                                            <option value="INTERIM">Intérim</option>
                                            <option value="STAGE">Stage</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Statut</label>
                                        <select 
                                            value={status} 
                                            onChange={e => setStatus(e.target.value as MissionStatus)}
                                            className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        >
                                            <option value="Draft">Brouillon</option>
                                            <option value="Active">Active</option>
                                            <option value="Paused">En pause</option>
                                            <option value="Ended">Terminée</option>
                                        </select>
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Début</label>
                                        <input 
                                            type="date" 
                                            value={startDate} 
                                            onChange={e => setStartDate(e.target.value)}
                                            className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                            required
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Fin (optionnel)</label>
                                        <input 
                                            type="date" 
                                            value={endDate} 
                                            onChange={e => setEndDate(e.target.value)}
                                            className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        />
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">TJM / Salaire</label>
                                        <input 
                                            type="number" 
                                            value={rate} 
                                            onChange={e => setRate(Number(e.target.value))}
                                            className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1 dark:text-gray-300">Lieu</label>
                                        <input 
                                            type="text" 
                                            value={location} 
                                            onChange={e => setLocation(e.target.value)}
                                            className="w-full p-3 rounded-lg border dark:bg-gray-800 dark:border-gray-700 focus:ring-2 focus:ring-primary-500 outline-none"
                                        />
                                    </div>
                                </div>

                                <button type="submit" className="w-full bg-gradient-button text-white font-bold py-4 rounded-xl mt-6 shadow-lg hover:opacity-90 transition-opacity flex items-center justify-center gap-2">
                                    <Icon name={editingMission.id ? "save" : "plus"} className="w-5 h-5" />
                                    <span>{editingMission.id ? "Mettre à jour la mission" : "Créer la mission"}</span>
                                </button>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

