export const TimesheetsView: React.FC<TimesheetsViewProps> = ({ timesheets, onUpdateStatus }) => {
    const { t } = useTranslation();
    const [selectedTimesheet, setSelectedTimesheet] = React.useState<Timesheet | null>(null);

    const getStatusBadge = (status: TimesheetStatus) => {
        const styles = {
            'Draft': 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300',
            'Submitted': 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300', // Pending in old code
